'use client';
import { useUserInfoStore } from '@/store/userInfo';
import { getTenantFromUrl } from '@/utils/getHostFromUrl';
import { usePathname, useRouter } from 'next/navigation';
import { useEffect, useRef } from 'react';

import {
    getPrimaryDashboardRoute,
    hasRouteAccess,
    isCalculatorHomePath,
    isPrivateRoute,
    shouldLandAwayFromCalculator,
} from '@/middlewares/permission-validator';
import { canEvaluateRouteAccess } from '@/functions/auth/permissions-load-state';
import { checkIsVisitorRoute } from '@/functions/check-is-visitor-route';
import { PERMISSIONS_CLIENT_MAX_AUTO_RETRIES } from '@/constants/permissions-fetch';

export default function RouteGuard({ children }: { children: React.ReactNode }) {
    const router = useRouter();
    const pathname = usePathname();
    const permissionRetryCount = useRef(0);
    const {
        data: {
            role,
            is_superuser: isSuperuser,
            is_staff: isStaff,
            user: profileUser,
            host: userHost,
        },
        permissions,
        permissionsLoadState,
        isUserLoading,
        isPermissionsLoading,
        getUserPermissions,
    } = useUserInfoStore();

    useEffect(() => {
        if (permissionsLoadState !== 'error') {
            return;
        }

        if (permissionRetryCount.current >= PERMISSIONS_CLIENT_MAX_AUTO_RETRIES) {
            return;
        }

        permissionRetryCount.current += 1;
        void getUserPermissions();
    }, [permissionsLoadState, getUserPermissions]);

    useEffect(() => {
        const currentPath = pathname || window.location.pathname;

        // Modo visitante: /entrar e /cadastro rodam no shell sem sessão, fora do RBAC.
        if (checkIsVisitorRoute(currentPath)) {
            return;
        }

        if (
            isUserLoading ||
            isPermissionsLoading ||
            !profileUser ||
            !canEvaluateRouteAccess(permissionsLoadState, permissions)
        ) {
            return;
        }

        const tenant = getTenantFromUrl();
        const primaryRoute = getPrimaryDashboardRoute(
            permissions ?? [],
            role,
            tenant,
            userHost,
        );

        if (
            isCalculatorHomePath(currentPath) &&
            shouldLandAwayFromCalculator(tenant, userHost)
        ) {
            router.push(primaryRoute);
            return;
        }

        if (isPrivateRoute(currentPath)) {
            const hasAccess = hasRouteAccess(
                currentPath,
                permissions ?? [],
                role,
                isSuperuser,
                isStaff,
            );

            if (!hasAccess) {
                if (currentPath !== primaryRoute && currentPath !== primaryRoute + '/') {
                    router.push(primaryRoute);
                }
            }
        }
    }, [
        role,
        isSuperuser,
        isStaff,
        profileUser,
        userHost,
        permissions,
        permissionsLoadState,
        isUserLoading,
        isPermissionsLoading,
        router,
        pathname,
    ]);

    return <>{children}</>;
}

