import { expect } from '@jest/globals';
import { checkIsVisitorRoute } from '@/functions/check-is-visitor-route';

describe('checkIsVisitorRoute', () => {
    it('reconhece /entrar e /cadastro, inclusive subrotas', () => {
        expect(checkIsVisitorRoute('/entrar')).toBe(true);
        expect(checkIsVisitorRoute('/entrar/')).toBe(true);
        expect(checkIsVisitorRoute('/cadastro')).toBe(true);
        expect(checkIsVisitorRoute('/cadastro/confirmar')).toBe(true);
    });

    it('não confunde com /cadastro-funcionario nem com rotas privadas', () => {
        expect(checkIsVisitorRoute('/cadastro-funcionario')).toBe(false);
        expect(checkIsVisitorRoute('/crm/broker')).toBe(false);
        expect(checkIsVisitorRoute('/')).toBe(false);
    });
});

