'use client';

import { usePathname } from 'next/navigation';

import { checkIsVisitorRoute } from '@/functions/check-is-visitor-route';
import { useUserInfoStore } from '@/store/userInfo';

/**
 * Modo visitante do shell: rota de visitante (/entrar, /cadastro) sem sessão.
 * Enquanto o perfil carrega não dá pra saber, então o shell segue o fluxo logado
 * (skeleton) e só vira visitante quando `fetchUserInfo` confirma que não há token.
 * Com sessão, a mesma rota mostra o shell logado normal.
 */
export function useVisitorMode(): boolean {
    const pathname = usePathname();
    const isUserLoading = useUserInfoStore((state) => state.isUserLoading);
    const hasSession = useUserInfoStore((state) => Boolean(state.data.user));

    return checkIsVisitorRoute(pathname ?? '') && !isUserLoading && !hasSession;
}

