1	import { getWebSocketUrl as getWebSocketUrlFromConfig } from '@/config/environment.config';
2	import { checkIsVisitorRoute } from '@/functions/check-is-visitor-route';
3	import { isUnauthenticatedProxyApiUrl } from '@/lib/api/is-unauthenticated-proxy-api-path';
4	import axios, { AxiosError, InternalAxiosRequestConfig } from 'axios';
5	import { getTenantFromUrl } from './getHostFromUrl';
6	
7	interface DirectApiRequestConfig extends InternalAxiosRequestConfig {
8	    __retryAfterRefresh?: boolean;
9	}
10	
11	const TOKEN_CACHE_TTL_MS = 5000;
12	const EMPTY_TOKEN_CACHE_TTL_MS = 1000;
13	
14	let cachedToken: string | null = null;
15	let cachedTokenExpiresAt = 0;
16	let inflightTokenRequest: Promise<string | null> | null = null;
17	
18	/** Rotas de API acessíveis sem sessão (público + render PDF interno). */
19	function isPublicApiRequestUrl(url?: string): boolean {
20	    return isUnauthenticatedProxyApiUrl(url);
21	}
22	
23	function isPublicAppPathname(pathname: string): boolean {
24	    return (
25	        pathname.startsWith('/publico/') || pathname.startsWith('/internal/proposta-digital')
26	    );
27	}
28	
29	/** Páginas de fluxo de auth sem sessão — não precisam consultar o cookie no servidor (evita vários 401 no log). */
30	function shouldSkipVerificationTokenFetch(pathname: string): boolean {
31	    if (pathname === '/auth/signin') return true;
32	    if (pathname === '/auth/signup' || pathname.startsWith('/auth/signup/')) return true;
33	    if (pathname === '/auth/two-step-verification') return true;
34	    if (checkIsVisitorRoute(pathname)) return true;
35	    if (isPublicAppPathname(pathname)) return true;
36	    return false;
37	}
38	
39	/**
40	 * Obtém a URL da API baseada no ambiente (client-side)
41	 * Usa variáveis NEXT_PUBLIC_* que são disponíveis no browser
42	 */
43	const getDirectApiUrl = (): string => {
44	    const appEnv = process.env.NEXT_PUBLIC_APP_ENV;
45	
46	    const isHomol = appEnv === 'homol' || appEnv === 'homologation' || appEnv === 'staging';
47	    const isProduction = appEnv === 'production' || appEnv === 'prod';
48	
49	    if (isHomol) {
50	        const homolUrl = process.env.NEXT_PUBLIC_HOMOL_API_URL || process.env.NEXT_PUBLIC_HOMOL_URL;
51	        if (homolUrl) return homolUrl;
52	    }
53	
54	    if (isProduction) {
55	        const prodUrl = process.env.NEXT_PUBLIC_PROD_API_URL;
56	        if (prodUrl) return prodUrl;
57	    }
58	
59	    return process.env.NEXT_PUBLIC_DEV_API_URL || 'http://127.0.0.1:8000';
60	};
61	
62	/**
63	 * Fetches the Bearer token from httpOnly cookies via the Next route.
64	 * With forceRefresh: skips the client TTL cache and hits the server again so
65	 * verification-token can rotate the access JWT (and Set-Cookie) when needed.
66	 */
67	export const getTokenViaAPI = async (
68	    { forceRefresh = false }: { forceRefresh?: boolean } = {},
69	): Promise<string | null> => {
70	    if (typeof window === 'undefined') {
71	        try {
72	            const [{ cookies }, { getSessionTokensFromCookies }] = await Promise.all([
73	                import('next/headers'),
74	                import('@/lib/auth/auth-cookies'),
75	            ]);
76	            return getSessionTokensFromCookies(await cookies()).access;
77	        } catch {
78	            return null;
79	        }
80	    }
81	
82	    const now = Date.now();
83	
84	    if (!forceRefresh && cachedTokenExpiresAt > now) {
85	        return cachedToken;
86	    }
87	
88	    if (
89	        typeof window !== 'undefined' &&
90	        !forceRefresh &&
91	        shouldSkipVerificationTokenFetch(window.location.pathname)
92	    ) {
93	        cachedToken = null;
94	        cachedTokenExpiresAt = Date.now() + EMPTY_TOKEN_CACHE_TTL_MS;
95	        return null;
96	    }
97	
98	    if (!forceRefresh && inflightTokenRequest) {
99	        return inflightTokenRequest;
100	    }
101	
102	    const fetchPromise = fetch('/api/authentication/verification-token', {
103	        credentials: 'include',
104	    })
105	        .then(async (response) => {
106	            if (!response.ok) {
107	                cachedToken = null;
108	                cachedTokenExpiresAt = Date.now() + EMPTY_TOKEN_CACHE_TTL_MS;
109	                return null;
110	            }
111	
112	            const { token } = await response.json();
113	            cachedToken = token ?? null;
114	            cachedTokenExpiresAt =
115	                Date.now() + (token ? TOKEN_CACHE_TTL_MS : EMPTY_TOKEN_CACHE_TTL_MS);
116	            return cachedToken;
117	        })
118	        .catch((error) => {
119	            cachedToken = null;
120	            cachedTokenExpiresAt = Date.now() + EMPTY_TOKEN_CACHE_TTL_MS;
121	            console.warn('❌ Erro ao buscar token via API:', error);
122	            return null;
123	        })
124	        .finally(() => {
125	            if (inflightTokenRequest === fetchPromise) {
126	                inflightTokenRequest = null;
127	            }
128	        });
129	
130	    inflightTokenRequest = fetchPromise;
131	    return fetchPromise;
132	};
133	
134	export const clearClientTokenCache = (): void => {
135	    cachedToken = null;
136	    cachedTokenExpiresAt = 0;
137	    inflightTokenRequest = null;
138	};
139	
140	const getBaseUrl = () => {
141	    if (typeof window !== 'undefined') {
142	        return `${window.location.protocol}//${window.location.host}`;
143	    }
144	    if (process.env.NEXT_PUBLIC_BASE_URL) return process.env.NEXT_PUBLIC_BASE_URL;
145	    if (process.env.VERCEL_URL) return `https://${process.env.VERCEL_URL}`;
146	    return `http://localhost:${process.env.PORT ?? '3000'}`;
147	};
148	
149	interface ISsrRequestContext {
150	    host: string;
151	    proto: string;
152	    cookie: string | null;
153	    tenant: string;
154	    accessToken: string | null;
155	    refreshToken: string | null;
156	}
157	
158	/**
159	 * Origem/sessão da request de entrada quando o código roda no servidor (SSR).
160	 * Sem isso o baseURL caía no fallback localhost:3000, que não existe na Lambda
161	 * da Vercel — era o ECONNREFUSED dominante nos logs de SSR (memória/broker).
162	 */
163	async function getSsrRequestContext(): Promise<ISsrRequestContext | null> {
164	    if (typeof window !== 'undefined') return null;
165	    try {
166	        const [{ headers, cookies }, { getSessionTokensFromCookies }] = await Promise.all([
167	            import('next/headers'),
168	            import('@/lib/auth/auth-cookies'),
169	        ]);
170	        const [requestHeaders, cookieStore] = await Promise.all([headers(), cookies()]);
171	        const sessionTokens = getSessionTokensFromCookies(cookieStore);
172	        const host = (
173	            requestHeaders.get('x-forwarded-host') ?? requestHeaders.get('host') ?? ''
174	        )
175	            .split(',')[0]
176	            ?.trim();
177	        if (!host) return null;
178	        return {
179	            host,
180	            proto:
181	                (requestHeaders.get('x-forwarded-proto') ?? '').split(',')[0]?.trim() ||
182	                (host.includes('localhost') ? 'http' : 'https'),
183	            cookie: requestHeaders.get('cookie'),
184	            tenant: getTenantFromUrl(host),
185	            accessToken: sessionTokens.access,
186	            refreshToken: sessionTokens.refresh,
187	        };
188	    } catch {
189	        return null;
190	    }
191	}
192	
193	/**
194	 * No SSR o /api/proxy é redundante — ele existe para converter o cookie do
195	 * browser em Bearer — e self-fetch dentro de rota dinâmica já causou outage
196	 * em prod (ver og-asset-loader.ts). Então `api` chama o Django direto com o
197	 * Bearer lido do cookie da request; `localApi` (rotas Next locais, que leem
198	 * cookies) segue para a origem da própria request.
199	 */
200	async function applySsrRequestContext(
201	    config: InternalAxiosRequestConfig,
202	    target: 'django' | 'self',
203	): Promise<InternalAxiosRequestConfig> {
204	    const context = await getSsrRequestContext();
205	    if (!context) return config;
206	
207	    config.headers['x-tenant'] = context.tenant;
208	
209	    if (target === 'django') {
210	        config.baseURL = getDirectApiUrl();
211	        if (context.accessToken && !config.headers['Authorization']) {
212	            config.headers['Authorization'] = `Bearer ${context.accessToken}`;
213	        }
214	        // Mesmo critério do /api/proxy: cookie só vai ao Django em paths públicos (sessão pública de Due).
215	        if (context.cookie && !config.headers['Cookie'] && isPublicApiRequestUrl(config.url)) {
216	            config.headers['Cookie'] = context.cookie;
217	        }
218	    } else {
219	        config.baseURL = `${context.proto}://${context.host}`;
220	        if (context.cookie && !config.headers['Cookie']) {
221	            config.headers['Cookie'] = context.cookie;
222	        }
223	    }
224	    return config;
225	}
226	
227	const api = axios.create({
228	    baseURL: `${getBaseUrl()}/api/proxy`,
229	    withCredentials: true,
230	    headers: {
231	        'Content-Type': 'application/json',
232	    },
233	});
234	
235	api.interceptors.request.use(async (config) => {
236	    const resolved = await applySsrRequestContext(config, 'django');
237	    if (resolved.data instanceof FormData) {
238	        delete resolved.headers['Content-Type'];
239	    }
240	    return resolved;
241	});
242	
243	let activeSsrRefreshPromise: Promise<string | null> | null = null;
244	let activeSsrRefreshToken: string | null = null;
245	
246	/**
247	 * Renova o access token no servidor batendo direto no Django
248	 * (`/api/token/refresh/`), mesmo fluxo do /api/proxy. O novo cookie não é
249	 * persistido no browser a partir do SSR — o client re-hidrata e refaz a query
250	 * com refresh próprio se precisar; aqui o objetivo é só completar a chamada.
251	 */
252	async function refreshSsrAccessToken(context: ISsrRequestContext): Promise<string | null> {
253	    if (!context.refreshToken) return null;
254	    if (activeSsrRefreshPromise && activeSsrRefreshToken === context.refreshToken) {
255	        return activeSsrRefreshPromise;
256	    }
257	
258	    activeSsrRefreshToken = context.refreshToken;
259	    activeSsrRefreshPromise = axios
260	        .post(
261	            `${getDirectApiUrl()}/api/token/refresh/`,
262	            { refresh: context.refreshToken },
263	            { headers: { 'x-tenant': context.tenant } },
264	        )
265	        .then((res) => (res.data?.access as string | undefined) ?? null)
266	        .catch(() => null)
267	        .finally(() => {
268	            activeSsrRefreshPromise = null;
269	            activeSsrRefreshToken = null;
270	        });
271	
272	    return activeSsrRefreshPromise;
273	}
274	
275	api.interceptors.response.use(
276	    (response) => response,
277	    async (error) => {
278	        const cfg = error.config as DirectApiRequestConfig | undefined;
279	
280	        if (
281	            typeof window === 'undefined' &&
282	            error.response?.status === 401 &&
283	            cfg &&
284	            !cfg.__retryAfterRefresh
285	        ) {
286	            cfg.__retryAfterRefresh = true;
287	            const context = await getSsrRequestContext();
288	            const newAccessToken = context ? await refreshSsrAccessToken(context) : null;
289	            if (newAccessToken) {
290	                cfg.headers['Authorization'] = `Bearer ${newAccessToken}`;
291	                return api.request(cfg);
292	            }
293	        }
294	
295	        if (error.response?.status === 401) {
296	            const href = typeof window !== 'undefined' ? window.location.href : '';
297	            const pathname = typeof window !== 'undefined' ? window.location.pathname : '';
298	            const isAuthPage = href.includes('/auth/signin') || href.includes('/auth/signup');
299	            const isLogoutCall = error.config?.url?.includes('/api/authentication/logout');
300	            const isTokenVerification = error.config?.url?.includes(
301	                '/api/authentication/verification-token',
302	            );
303	            // Modo visitante: sem sessão o 401 é o esperado, não expulsa pro login.
304	            const isPublicContext =
305	                isPublicAppPathname(pathname) ||
306	                checkIsVisitorRoute(pathname) ||
307	                isPublicApiRequestUrl(error.config?.url);
308	
309	            if (typeof window !== 'undefined' && !isAuthPage && !isLogoutCall && !isTokenVerification && !isPublicContext) {
310	                window.location.href = '/auth/signin';
311	            }
312	        }
313	        return Promise.reject(error);
314	    },
315	);
316	
317	export const directApi = axios.create({
318	    baseURL: getDirectApiUrl(),
319	    withCredentials: false,
320	    headers: {
321	        'Content-Type': 'application/json',
322	    },
323	});
324	
325	/**
326	 * Obtém a URL do WebSocket baseada no ambiente (client-side)
327	 * Converte automaticamente http/https para ws/wss
328	 * @deprecated Use diretamente `getWebSocketUrl` de `@/config/environment.config`.
329	 */
330	export const getWebSocketUrl = getWebSocketUrlFromConfig;
331	
332	directApi.interceptors.request.use(async (config) => {
333	    const currentToken = await getTokenViaAPI();
334	
335	    if (currentToken) {
336	        config.headers.Authorization = `Bearer ${currentToken}`;
337	    }
338	
339	    const ssrContext = await getSsrRequestContext();
340	    const tenant = ssrContext?.tenant || getTenantFromUrl();
341	    config.headers['x-tenant'] = tenant || 'celer';
342	
343	    // Remover Content-Type para FormData (axios lida com isso automaticamente)
344	    if (config.data instanceof FormData) {
345	        delete config.headers['Content-Type'];
346	    }
347	
348	    return config;
349	});
350	
351	directApi.interceptors.response.use(
352	    (response) => response,
353	    async (error: AxiosError) => {
354	        const cfg = error.config as DirectApiRequestConfig | undefined;
355	        if (!cfg || cfg.__retryAfterRefresh || error.response?.status !== 401) {
356	            return Promise.reject(error);
357	        }
358	        cfg.__retryAfterRefresh = true;
359	        await getTokenViaAPI({ forceRefresh: true });
360	        return directApi.request(cfg);
361	    },
362	);
363	
364	export const localApi = axios.create({
365	    baseURL: getBaseUrl(),
366	    withCredentials: true,
367	    headers: {
368	        'Content-Type': 'application/json',
369	    },
370	});
