import { getWebSocketUrl as getWebSocketUrlFromConfig } from '@/config/environment.config';
import { checkIsVisitorRoute } from '@/functions/check-is-visitor-route';
import { isUnauthenticatedProxyApiUrl } from '@/lib/api/is-unauthenticated-proxy-api-path';
import axios, { AxiosError, InternalAxiosRequestConfig } from 'axios';
import { getTenantFromUrl } from './getHostFromUrl';

interface DirectApiRequestConfig extends InternalAxiosRequestConfig {
    __retryAfterRefresh?: boolean;
}

const TOKEN_CACHE_TTL_MS = 5000;
const EMPTY_TOKEN_CACHE_TTL_MS = 1000;

let cachedToken: string | null = null;
let cachedTokenExpiresAt = 0;
let inflightTokenRequest: Promise<string | null> | null = null;

/** Rotas de API acessíveis sem sessão (público + render PDF interno). */
function isPublicApiRequestUrl(url?: string): boolean {
    return isUnauthenticatedProxyApiUrl(url);
}

function isPublicAppPathname(pathname: string): boolean {
    return (
        pathname.startsWith('/publico/') || pathname.startsWith('/internal/proposta-digital')
    );
}

/** Páginas de fluxo de auth sem sessão — não precisam consultar o cookie no servidor (evita vários 401 no log). */
function shouldSkipVerificationTokenFetch(pathname: string): boolean {
    if (pathname === '/auth/signin') return true;
    if (pathname === '/auth/signup' || pathname.startsWith('/auth/signup/')) return true;
    if (pathname === '/auth/two-step-verification') return true;
    if (checkIsVisitorRoute(pathname)) return true;
    if (isPublicAppPathname(pathname)) return true;
    return false;
}

/**
 * Obtém a URL da API baseada no ambiente (client-side)
 * Usa variáveis NEXT_PUBLIC_* que são disponíveis no browser
 */
const getDirectApiUrl = (): string => {
    const appEnv = process.env.NEXT_PUBLIC_APP_ENV;

    const isHomol = appEnv === 'homol' || appEnv === 'homologation' || appEnv === 'staging';
    const isProduction = appEnv === 'production' || appEnv === 'prod';

    if (isHomol) {
        const homolUrl = process.env.NEXT_PUBLIC_HOMOL_API_URL || process.env.NEXT_PUBLIC_HOMOL_URL;
        if (homolUrl) return homolUrl;
    }

    if (isProduction) {
        const prodUrl = process.env.NEXT_PUBLIC_PROD_API_URL;
        if (prodUrl) return prodUrl;
    }

    return process.env.NEXT_PUBLIC_DEV_API_URL || 'http://127.0.0.1:8000';
};

/**
 * Fetches the Bearer token from httpOnly cookies via the Next route.
 * With forceRefresh: skips the client TTL cache and hits the server again so
 * verification-token can rotate the access JWT (and Set-Cookie) when needed.
 */
export const getTokenViaAPI = async (
    { forceRefresh = false }: { forceRefresh?: boolean } = {},
): Promise<string | null> => {
    if (typeof window === 'undefined') {
        try {
            const [{ cookies }, { getSessionTokensFromCookies }] = await Promise.all([
                import('next/headers'),
                import('@/lib/auth/auth-cookies'),
            ]);
            return getSessionTokensFromCookies(await cookies()).access;
        } catch {
            return null;
        }
    }

    const now = Date.now();

    if (!forceRefresh && cachedTokenExpiresAt > now) {
        return cachedToken;
    }

    if (
        typeof window !== 'undefined' &&
        !forceRefresh &&
        shouldSkipVerificationTokenFetch(window.location.pathname)
    ) {
        cachedToken = null;
        cachedTokenExpiresAt = Date.now() + EMPTY_TOKEN_CACHE_TTL_MS;
        return null;
    }

    if (!forceRefresh && inflightTokenRequest) {
        return inflightTokenRequest;
    }

    const fetchPromise = fetch('/api/authentication/verification-token', {
        credentials: 'include',
    })
        .then(async (response) => {
            if (!response.ok) {
                cachedToken = null;
                cachedTokenExpiresAt = Date.now() + EMPTY_TOKEN_CACHE_TTL_MS;
                return null;
            }

            const { token } = await response.json();
            cachedToken = token ?? null;
            cachedTokenExpiresAt =
                Date.now() + (token ? TOKEN_CACHE_TTL_MS : EMPTY_TOKEN_CACHE_TTL_MS);
            return cachedToken;
        })
        .catch((error) => {
            cachedToken = null;
            cachedTokenExpiresAt = Date.now() + EMPTY_TOKEN_CACHE_TTL_MS;
            console.warn('❌ Erro ao buscar token via API:', error);
            return null;
        })
        .finally(() => {
            if (inflightTokenRequest === fetchPromise) {
                inflightTokenRequest = null;
            }
        });

    inflightTokenRequest = fetchPromise;
    return fetchPromise;
};

export const clearClientTokenCache = (): void => {
    cachedToken = null;
    cachedTokenExpiresAt = 0;
    inflightTokenRequest = null;
};

const getBaseUrl = () => {
    if (typeof window !== 'undefined') {
        return `${window.location.protocol}//${window.location.host}`;
    }
    if (process.env.NEXT_PUBLIC_BASE_URL) return process.env.NEXT_PUBLIC_BASE_URL;
    if (process.env.VERCEL_URL) return `https://${process.env.VERCEL_URL}`;
    return `http://localhost:${process.env.PORT ?? '3000'}`;
};

interface ISsrRequestContext {
    host: string;
    proto: string;
    cookie: string | null;
    tenant: string;
    accessToken: string | null;
    refreshToken: string | null;
}

/**
 * Origem/sessão da request de entrada quando o código roda no servidor (SSR).
 * Sem isso o baseURL caía no fallback localhost:3000, que não existe na Lambda
 * da Vercel — era o ECONNREFUSED dominante nos logs de SSR (memória/broker).
 */
async function getSsrRequestContext(): Promise<ISsrRequestContext | null> {
    if (typeof window !== 'undefined') return null;
    try {
        const [{ headers, cookies }, { getSessionTokensFromCookies }] = await Promise.all([
            import('next/headers'),
            import('@/lib/auth/auth-cookies'),
        ]);
        const [requestHeaders, cookieStore] = await Promise.all([headers(), cookies()]);
        const sessionTokens = getSessionTokensFromCookies(cookieStore);
        const host = (
            requestHeaders.get('x-forwarded-host') ?? requestHeaders.get('host') ?? ''
        )
            .split(',')[0]
            ?.trim();
        if (!host) return null;
        return {
            host,
            proto:
                (requestHeaders.get('x-forwarded-proto') ?? '').split(',')[0]?.trim() ||
                (host.includes('localhost') ? 'http' : 'https'),
            cookie: requestHeaders.get('cookie'),
            tenant: getTenantFromUrl(host),
            accessToken: sessionTokens.access,
            refreshToken: sessionTokens.refresh,
        };
    } catch {
        return null;
    }
}

/**
 * No SSR o /api/proxy é redundante — ele existe para converter o cookie do
 * browser em Bearer — e self-fetch dentro de rota dinâmica já causou outage
 * em prod (ver og-asset-loader.ts). Então `api` chama o Django direto com o
 * Bearer lido do cookie da request; `localApi` (rotas Next locais, que leem
 * cookies) segue para a origem da própria request.
 */
async function applySsrRequestContext(
    config: InternalAxiosRequestConfig,
    target: 'django' | 'self',
): Promise<InternalAxiosRequestConfig> {
    const context = await getSsrRequestContext();
    if (!context) return config;

    config.headers['x-tenant'] = context.tenant;

    if (target === 'django') {
        config.baseURL = getDirectApiUrl();
        if (context.accessToken && !config.headers['Authorization']) {
            config.headers['Authorization'] = `Bearer ${context.accessToken}`;
        }
        // Mesmo critério do /api/proxy: cookie só vai ao Django em paths públicos (sessão pública de Due).
        if (context.cookie && !config.headers['Cookie'] && isPublicApiRequestUrl(config.url)) {
            config.headers['Cookie'] = context.cookie;
        }
    } else {
        config.baseURL = `${context.proto}://${context.host}`;
        if (context.cookie && !config.headers['Cookie']) {
            config.headers['Cookie'] = context.cookie;
        }
    }
    return config;
}

const api = axios.create({
    baseURL: `${getBaseUrl()}/api/proxy`,
    withCredentials: true,
    headers: {
        'Content-Type': 'application/json',
    },
});

api.interceptors.request.use(async (config) => {
    const resolved = await applySsrRequestContext(config, 'django');
    if (resolved.data instanceof FormData) {
        delete resolved.headers['Content-Type'];
    }
    return resolved;
});

let activeSsrRefreshPromise: Promise<string | null> | null = null;
let activeSsrRefreshToken: string | null = null;

/**
 * Renova o access token no servidor batendo direto no Django
 * (`/api/token/refresh/`), mesmo fluxo do /api/proxy. O novo cookie não é
 * persistido no browser a partir do SSR — o client re-hidrata e refaz a query
 * com refresh próprio se precisar; aqui o objetivo é só completar a chamada.
 */
async function refreshSsrAccessToken(context: ISsrRequestContext): Promise<string | null> {
    if (!context.refreshToken) return null;
    if (activeSsrRefreshPromise && activeSsrRefreshToken === context.refreshToken) {
        return activeSsrRefreshPromise;
    }

    activeSsrRefreshToken = context.refreshToken;
    activeSsrRefreshPromise = axios
        .post(
            `${getDirectApiUrl()}/api/token/refresh/`,
            { refresh: context.refreshToken },
            { headers: { 'x-tenant': context.tenant } },
        )
        .then((res) => (res.data?.access as string | undefined) ?? null)
        .catch(() => null)
        .finally(() => {
            activeSsrRefreshPromise = null;
            activeSsrRefreshToken = null;
        });

    return activeSsrRefreshPromise;
}

api.interceptors.response.use(
    (response) => response,
    async (error) => {
        const cfg = error.config as DirectApiRequestConfig | undefined;

        if (
            typeof window === 'undefined' &&
            error.response?.status === 401 &&
            cfg &&
            !cfg.__retryAfterRefresh
        ) {
            cfg.__retryAfterRefresh = true;
            const context = await getSsrRequestContext();
            const newAccessToken = context ? await refreshSsrAccessToken(context) : null;
            if (newAccessToken) {
                cfg.headers['Authorization'] = `Bearer ${newAccessToken}`;
                return api.request(cfg);
            }
        }

        if (error.response?.status === 401) {
            const href = typeof window !== 'undefined' ? window.location.href : '';
            const pathname = typeof window !== 'undefined' ? window.location.pathname : '';
            const isAuthPage = href.includes('/auth/signin') || href.includes('/auth/signup');
            const isLogoutCall = error.config?.url?.includes('/api/authentication/logout');
            const isTokenVerification = error.config?.url?.includes(
                '/api/authentication/verification-token',
            );
            // Modo visitante: sem sessão o 401 é o esperado, não expulsa pro login.
            const isPublicContext =
                isPublicAppPathname(pathname) ||
                checkIsVisitorRoute(pathname) ||
                isPublicApiRequestUrl(error.config?.url);

            if (typeof window !== 'undefined' && !isAuthPage && !isLogoutCall && !isTokenVerification && !isPublicContext) {
                window.location.href = '/auth/signin';
            }
        }
        return Promise.reject(error);
    },
);

export const directApi = axios.create({
    baseURL: getDirectApiUrl(),
    withCredentials: false,
    headers: {
        'Content-Type': 'application/json',
    },
});

/**
 * Obtém a URL do WebSocket baseada no ambiente (client-side)
 * Converte automaticamente http/https para ws/wss
 * @deprecated Use diretamente `getWebSocketUrl` de `@/config/environment.config`.
 */
export const getWebSocketUrl = getWebSocketUrlFromConfig;

directApi.interceptors.request.use(async (config) => {
    const currentToken = await getTokenViaAPI();

    if (currentToken) {
        config.headers.Authorization = `Bearer ${currentToken}`;
    }

    const ssrContext = await getSsrRequestContext();
    const tenant = ssrContext?.tenant || getTenantFromUrl();
    config.headers['x-tenant'] = tenant || 'celer';

    // Remover Content-Type para FormData (axios lida com isso automaticamente)
    if (config.data instanceof FormData) {
        delete config.headers['Content-Type'];
    }

    return config;
});

directApi.interceptors.response.use(
    (response) => response,
    async (error: AxiosError) => {
        const cfg = error.config as DirectApiRequestConfig | undefined;
        if (!cfg || cfg.__retryAfterRefresh || error.response?.status !== 401) {
            return Promise.reject(error);
        }
        cfg.__retryAfterRefresh = true;
        await getTokenViaAPI({ forceRefresh: true });
        return directApi.request(cfg);
    },
);

export const localApi = axios.create({
    baseURL: getBaseUrl(),
    withCredentials: true,
    headers: {
        'Content-Type': 'application/json',
    },
});

localApi.interceptors.request.use(
    async (config) => {
        const resolved = await applySsrRequestContext(config, 'self');
        const tenant = getTenantFromUrl();
        resolved.headers['x-tenant'] = resolved.headers['x-tenant'] || tenant || 'celer';
        return resolved;
    },
    (error) => Promise.reject(error),
);

localApi.interceptors.response.use(
    (response) => response,
    (error) => {
        if (error.response?.status === 401) {
            const href = typeof window !== 'undefined' ? window.location.href : '';
            const pathname = typeof window !== 'undefined' ? window.location.pathname : '';
            const isAuthPage = href.includes('/auth/signin') || href.includes('/auth/signup');
            const isLogoutCall = error.config?.url?.includes('/api/authentication/logout');
            const isTokenVerification = error.config?.url?.includes(
                '/api/authentication/verification-token',
            );
            // Modo visitante: sem sessão o 401 é o esperado, não expulsa pro login.
            const isPublicContext =
                isPublicAppPathname(pathname) ||
                checkIsVisitorRoute(pathname) ||
                isPublicApiRequestUrl(error.config?.url);

            if (typeof window !== 'undefined' && !isAuthPage && !isLogoutCall && !isTokenVerification && !isPublicContext) {
                window.location.href = '/auth/signin';
            }
        }
        return Promise.reject(error);
    },
);

export default api;

